using System.Text.Json;
using Sia.Spirv.Compiler.Compilation;
using Sia.Spirv.Compiler.Translation;
using Sia.Spirv.Compiler.Translation.Back;
using Sia.Spirv;

if (args[0] == "il") {
    string assembly = Path.GetFullPath(args[1]), destinationRoot = Path.GetFullPath(args[2]);
    var compiler = new SpirvCompiler();
    var target = SpirvCompilationTarget.Default with { Version = 0x00010300, KernelAbi = SpirvKernelAbi.WebGpu };
    var offline = compiler.CompileAssembly(new(assembly, Path.Combine(destinationRoot, "offline")) {
        Target = target with { Version = 0x00010500 }, ToolchainDirectory = Path.GetFullPath(args[3]), EmitWgsl = true, EmitLlvmIr = true, OptimizationLevel = 3
    });
    var runtime = Path.Combine(destinationRoot, "runtime"); Directory.CreateDirectory(runtime);
    foreach (var artifact in offline) {
        var module = compiler.CompileModule(new(File.ReadAllBytes(assembly), artifact.Kernel.MetadataToken, File.ReadAllBytes(typeof(Gpu).Assembly.Location)));
        string name = artifact.Kernel.QualifiedName;
        byte[] binary = SpirvWriter.Write(module, target);
        File.WriteAllBytes(Path.Combine(runtime, name + ".spv"), binary);
        File.WriteAllText(Path.Combine(runtime, name + ".wgsl"), ShaderTranslator.SpirvToWgsl(binary, target));
    }
    Console.WriteLine($"Compiled {offline.Count} kernels through offline and runtime paths.");
    return;
}

string destination = Path.GetFullPath(args[0]);
Directory.CreateDirectory(destination);
var inputs = JsonSerializer.Deserialize<Input[]>(File.ReadAllText(args[1]))!;
var results = new List<object>();
foreach (var input in inputs) {
    try {
        byte[] binary = input.Path.EndsWith(".spv", StringComparison.OrdinalIgnoreCase) ? File.ReadAllBytes(input.Path)
            : ShaderTranslator.WgslToSpirv(File.ReadAllText(input.Path), SpirvCompilationTarget.Default);
        File.WriteAllBytes(Path.Combine(destination, input.Name + ".spv"), binary);
        string? wgsl = null, error = null;
        try { wgsl = ShaderTranslator.SpirvToWgsl(binary, SpirvCompilationTarget.Default); File.WriteAllText(Path.Combine(destination, input.Name + ".wgsl"), wgsl); }
        catch (Exception e) { error = e.ToString(); }
        results.Add(new { input.Name, input.Path, Compiled = true, Roundtrip = error is null, Bytes = binary.Length, Error = error });
    }
    catch (Exception e) { results.Add(new { input.Name, input.Path, Compiled = false, Roundtrip = false, Bytes = 0, Error = e.ToString() }); }
}
File.WriteAllText(Path.Combine(destination, "results.json"), JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true }));
Console.WriteLine($"Processed {inputs.Length} inputs.");

record Input(string Name, string Path);

